{
  "apiVersion": "apps/v1",
  "kind": "Deployment",
  "metadata": {
    "annotations": {
      "helm.sh/resource-policy": "keep"
    },
    "name": "hermes"
  },
  "spec": {
    "replicas": 1,
    "selector": {
      "matchLabels": {
        "app": "hermes"
      }
    },
    "strategy": {
      "type": "Recreate"
    },
    "template": {
      "metadata": {
        "labels": {
          "app": "hermes"
        }
      },
      "spec": {
        "automountServiceAccountToken": false,
        "containers": [
          {
            "command": [
              "hermes",
              "-p",
              "default",
              "gateway",
              "run"
            ],
            "env": [
              {
                "name": "HERMES_SKIP_CONFIG_MIGRATION",
                "value": "1"
              },
              {
                "name": "HERMES_HOME",
                "value": "/opt/data/assistant"
              }
            ],
            "envFrom": [
              {
                "secretRef": {
                  "name": "hermes-env"
                }
              }
            ],
            "image": "{{ .Values.hermes.image }}",
            "name": "hermes",
            "ports": [
              {
                "containerPort": 8642
              }
            ],
            "readinessProbe": {
              "httpGet": {
                "path": "/health",
                "port": 8642
              },
              "initialDelaySeconds": 15
            },
            "resources": {
              "requests": {
                "cpu": "250m",
                "memory": "512Mi"
              }
            },
            "volumeMounts": [
              {
                "mountPath": "/opt/data/assistant",
                "name": "data"
              },
              {
                "mountPath": "/opt/data/assistant/config.yaml",
                "name": "config",
                "readOnly": true,
                "subPath": "config.yaml"
              }
            ]
          }
        ],
        "initContainers": [
          {
            "command": [
              "/bin/sh",
              "-ec",
              "chown 1000:1000 /state"
            ],
            "image": "busybox:1.37.0",
            "name": "state-owner",
            "volumeMounts": [
              {
                "mountPath": "/state",
                "name": "data"
              }
            ]
          }
        ],
        "volumes": [
          {
            "name": "data",
            "persistentVolumeClaim": {
              "claimName": "hermes-data"
            }
          },
          {
            "configMap": {
              "name": "hermes-config"
            },
            "name": "config"
          }
        ]
      }
    }
  }
}
